typedef enum logic {IDLE, GRANT1, GRANT2} state_t;
state_t state, next_state;

// State register
always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n)
        state <= IDLE;
    else
        state <= next_state;
end

// Next state and output logic
always_comb begin
    next_state = state;
    grant1 = 1'b0;
    grant2 = 1'b0;

    case (state)
        IDLE: begin
            if (req1) begin
                next_state = GRANT1;
                grant1 = 1'b1;  // Grant immediately
            end
            else if (req2) begin
                next_state = GRANT2;
                grant2 = 1'b1;  // Grant immediately
            end
        end

        GRANT1: begin
            if (!req1) begin
                next_state = IDLE;
            end
            else if (req2) begin
                grant1 = 1'b1;  // Keep grant while req1 still high
            end
        end

        GRANT2: begin
            if (!req2) begin
                next_state = IDLE;
            end
            else if (req1) begin
                grant2 = 1'b1;  // Keep grant while req2 still high
            end
        end
    endcase
