module binary_to_bcd_mealy (
    input logic clk,
    input logic rst_n,
    input logic [7:0] binary_in,
    input logic convert,
    output logic [3:0] bcd_out,
    output logic bcd_valid
);

typedef enum logic [2:0] {IDLE, SHIFT, ADD3, DONE} state_t;
state_t state, next_state;
logic [7:0] binary_reg;
logic [11:0] bcd_reg;
logic [2:0] bit_count;

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        binary_reg <= 8'b0;
        bcd_reg <= 12'b0;
        bit_count <= 3'b0;
    end else begin
        state <= next_state;
        if (state == SHIFT) begin
            binary_reg <= {binary_reg[6:0], 1'b0};
            bcd_reg <= {bcd_reg[10:0], binary_reg[7]};
            bit_count <= bit_count + 1;
        end
        if (state == ADD3)
            // Add 3 to each BCD digit > 4
            bcd_reg <= bcd_reg;
    end
end

always_comb begin
    next_state = state;
    bcd_out = 4'b0;
    bcd_valid = 1'b0;

    case (state)
        IDLE: begin
            if (convert) begin
                next_state = SHIFT;
                binary_reg = binary_in;
                bcd_reg = 12'b0;
                bit_count = 3'b0;
            end
        end

        SHIFT: begin
            if (bit_count == 3'b111) begin
                next_state = DONE;
                // Output on last shift
                bcd_out = bcd_reg[11:8];  // MSB digit
                bcd_valid = 1'b1;
            end else begin
                // Check if any BCD digit > 4
                if (bcd_reg[11:8] > 4 || bcd_reg[7:4] > 4 || bcd_reg[3:0] > 4)
                    next_state = ADD3;
            end
        end

        ADD3: begin
            // Immediate addition of 3 to digits > 4
            next_state = SHIFT;
        end

        DONE: begin
            bcd_out = bcd_reg[11:8];
            bcd_valid = 1'b1;
            next_state = IDLE;
        end
    endcase
end

endmodule,"

module spi_master_mealy (
    input logic clk,
    input logic rst_n,
    input logic start,
    input logic [7:0] tx_data,
    output logic sclk,
    output logic mosi,
    input logic miso,
    output logic [7:0] rx_data,
    output logic busy,
    output logic done
);

typedef enum logic [2:0] {IDLE, ASSERT_CS, CLK_LOW, CLK_HIGH, DONE_ST} state_t;
state_t state, next_state;
logic [2:0] bit_count;
logic [7:0] shift_reg;

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        bit_count <= 3'b0;
        shift_reg <= 8'b0;
    end else begin
        state <= next_state;
        if (state == CLK_LOW) begin
            shift_reg <= {shift_reg[6:0], miso};  // Sample on rising edge
            bit_count <= bit_count + 1;
        end
    end
end

always_comb begin
    next_state = state;
    sclk = 1'b0;
    mosi = 1'b0;
    busy = 1'b1;
    done = 1'b0;
    rx_data = shift_reg;

    case (state)
        IDLE: begin
            busy = 1'b0;
            if (start) begin
                next_state = ASSERT_CS;
                shift_reg = tx_data;
                bit_count = 3'b0;
            end
        end

        ASSERT_CS: begin
            next_state = CLK_LOW;  // Immediate transition
        end

        CLK_LOW: begin
            sclk = 1'b0;
            mosi = shift_reg[7];  // Output MSB first
            if (bit_count == 3'b111)  // Last bit
                next_state = DONE_ST;
            else
                next_state = CLK_HIGH;
        end

        CLK_HIGH: begin
            sclk = 1'b1;
            mosi = shift_reg[7];
            next_state = CLK_LOW;  // Immediate transition back
        end

        DONE_ST: begin
            done = 1'b1;  // Done signal
            next_state = IDLE;
        end
    endcase
end

endmodule,"

module crc_generator_mealy (
    input logic clk,
    input logic rst_n,
    input logic data_in,
    input logic data_valid,
    input logic crc_enable,
    output logic [7:0] crc_out,
    output logic crc_ready
);

typedef enum logic [1:0] {IDLE, PROCESS, FINAL} state_t;
state_t state, next_state;
logic [7:0] crc_reg;
logic [3:0] bit_count;

// CRC-8 polynomial: x^8 + x^2 + x + 1 (0x07)
parameter POLY = 8'h07;

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        crc_reg <= 8'hFF;  // Initial value
        bit_count <= 4'b0;
    end else begin
        state <= next_state;
        if (state == PROCESS) begin
            crc_reg <= crc_next;
            bit_count <= bit_count + 1;
        end
    end
end

always_comb begin
    logic [7:0] crc_next;
    next_state = state;
    crc_out = crc_reg;
    crc_ready = 1'b0;

    // CRC computation
    crc_next = crc_reg;
    if (data_valid) begin
        crc_next[0] = crc_reg[7] ^ data_in;
        crc_next[1] = crc_reg[0] ^ crc_reg[7] ^ data_in;
        crc_next[2] = crc_reg[1] ^ crc_reg[7] ^ data_in;
        crc_next[3] = crc_reg[2];
        crc_next[4] = crc_reg[3];
        crc_next[5] = crc_reg[4];
        crc_next[6] = crc_reg[5];
        crc_next[7] = crc_reg[6];
    end

    case (state)
        IDLE: begin
            if (crc_enable) begin
                next_state = PROCESS;
                bit_count = 4'b0;
                crc_reg = 8'hFF;
            end
        end

        PROCESS: begin
            if (bit_count == 4'b1000) begin  // 8 bits processed
                next_state = FINAL;
                crc_ready = 1'b1;  // CRC ready immediately
                crc_out = crc_reg;
            end
        end

        FINAL: begin
            crc_ready = 1'b1;
            crc_out = crc_reg;
            if (!crc_enable)
                next_state = IDLE;
        end
    endcase
end

endmodule,"

module vending_machine_mealy (
    input logic clk,
    input logic rst_n,
    input logic coin_25,  // Quarter
    input logic coin_10,  // Dime
    output logic dispense
);

typedef enum logic [1:0] {S0, S25, S35} state_t;
state_t state, next_state;

// State register
always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n)
        state <= S0;
    else
        state <= next_state;
end

// Next state and output logic
always_comb begin
    next_state = state;
    dispense = 1'b0;

    case (state)
        S0: begin
            if (coin_25) next_state = S25;
            else if (coin_10) next_state = S10;
        end

        S10: begin
            if (coin_25) begin
                next_state = S35;
                dispense = 1'b1;  // Total = 35 cents - dispense
            end
            else if (coin_10) next_state = S20;
        end

        S20: begin
            if (coin_25) begin
                next_state = S45;
                dispense = 1'b1;  // Total = 45 cents - dispense with change
            end
            else if (coin_10) next_state = S30;
        end

        S25: begin
            if (coin_10) begin
                next_state = S35;
                dispense = 1'b1;  // Total = 35 cents - dispense
            end
        end

        S30, S35, S45: begin
            // After dispense, go back to S0
            next_state = S0;
        end
    endcase
end

