module jpeg_huffman_encoder (
    input logic clk,
    input logic rst_n,
    input logic [7:0] data_byte,           // Input data byte
    input logic [5:0] run_length,           // Run length of zeros
    input logic [3:0] category,              // Category of non-zero value
    input logic [11:0] amplitude,            // Amplitude of non-zero value
    input logic valid_in,
    input logic last_block,
    output logic [15:0] encoded_bits,        // Huffman encoded bits
    output logic [3:0] bit_length,           // Length of encoded bits (1-16)
    output logic [3:0] code_count,           // Number of codes generated
    output logic done,
    output logic eob_detected
);

typedef enum logic [3:0] {
    IDLE,
    GET_DC_DIFF,
    ENCODE_DC,
    GET_AC_COEFF,
    ENCODE_AC_RUN,
    ENCODE_AC_SIZE,
    ENCODE_AC_AMPLITUDE,
    CHECK_EOB,
    INSERT_EOB,
    FLUSH,
    COMPLETE,
    WAIT
} state_t;

state_t state, next_state;
logic [15:0] huffman_code;
logic [3:0] huffman_len;
logic [5:0] zero_run;
logic [3:0] size_category;
logic [11:0] value_amplitude;
logic [2:0] ac_counter;
logic [7:0] bit_buffer;
logic [3:0] bit_pos;
logic [3:0] code_counter;

// Huffman tables (simplified JPEG tables)
typedef struct {
    logic [15:0] code;
    logic [3:0] length;
} huffman_entry_t;

// DC Huffman table (luminance)
huffman_entry_t dc_table [0:11] = '{
    '{16'h0000, 4'd2},  // 00
    '{16'h0002, 4'd3},  // 010
    '{16'h0003, 4'd3},  // 011
    '{16'h0004, 4'd3},  // 100
    '{16'h0005, 4'd3},  // 101
    '{16'h0006, 4'd3},  // 110
    '{16'h000E, 4'd4},  // 1110
    '{16'h001E, 4'd5},  // 11110
    '{16'h003E, 4'd6},  // 111110
    '{16'h007E, 4'd7},  // 1111110
    '{16'h00FE, 4'd8},  // 11111110
    '{16'h01FE, 4'd9}   // 111111110
};

// AC Huffman table (luminance) - simplified
huffman_entry_t ac_table [0:255] = '{
    // Run/Size combinations
    '{16'h0000, 4'd4},  // EOB
    '{16'h0001, 4'd2},  // 0/1
    '{16'h0002, 4'd2},  // 0/2
    '{16'h0003, 4'd3},  // 0/3
    // ... more entries (simplified for example)
    default: '{16'hFFFF, 4'd16}
};

always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        huffman_code <= 16'b0;
        huffman_len <= 4'b0;
        zero_run <= 6'b0;
        size_category <= 4'b0;
        value_amplitude <= 12'b0;
        ac_counter <= 3'b0;
        bit_buffer <= 8'b0;
        bit_pos <= 4'b0;
        code_counter <= 4'b0;
    end else begin
        state <= next_state;

        // Capture input data
        if (valid_in && state == IDLE) begin
            size_category <= category;
            zero_run <= run_length;
            value_amplitude <= amplitude;
        end

        // Update counters
        if (state == ENCODE_DC || state == ENCODE_AC_SIZE)
            code_counter <= code_counter + 1;

        if (state == ENCODE_AC_RUN)
            ac_counter <= ac_counter + 1;
    end
end

always_comb begin
    next_state = state;
    encoded_bits = huffman_code;
    bit_length = huffman_len;
    code_count = code_counter;
    done = 1'b0;
    eob_detected = 1'b0;

    // Huffman encoding logic
    logic [15:0] temp_code;
    logic [3:0] temp_len;
    logic [11:0] temp_amplitude;

    case (state)
        IDLE: begin
            code_counter = 4'b0;
            if (valid_in) begin
                next_state = GET_DC_DIFF;
            end
        end

        GET_DC_DIFF: begin
            // Get DC coefficient difference category
            if (size_category < 12) begin
                huffman_code = dc_table[size_category].code;
                huffman_len = dc_table[size_category].length;
                next_state = ENCODE_DC;
            end else begin
                next_state = WAIT;
            end
        end

        ENCODE_DC: begin
            encoded_bits = huffman_code;
            bit_length = huffman_len;

            // Append amplitude bits
            if (size_category > 0) begin
                temp_amplitude = value_amplitude;
                // Encode amplitude in lower bits
                encoded_bits = (huffman_code << size_category) |
                              (temp_amplitude & ((1 << size_category) - 1));
                bit_length = huffman_len + size_category;
            end

            next_state = GET_AC_COEFF;
            ac_counter = 3'b0;
        end

        GET_AC_COEFF: begin
            if (ac_counter < 8) begin  // Max 8 AC coefficients per block
                if (zero_run > 0) begin
                    // Encode run-length of zeros
                    next_state = ENCODE_AC_RUN;
                end else if (size_category > 0) begin
                    // Encode non-zero AC coefficient
                    next_state = ENCODE_AC_SIZE;
                end else begin
                    // Skip to next coefficient
                    ac_counter = ac_counter + 1;
                end
            end else begin
                next_state = CHECK_EOB;
            end
        end

        ENCODE_AC_RUN: begin
            // Encode run-length of zeros (simplified)
            temp_code = ac_table[zero_run * 16 + size_category].code;
            temp_len = ac_table[zero_run * 16 + size_category].length;

            if (temp_len > 0) begin
                huffman_code = temp_code;
                huffman_len = temp_len;
                next_state = ENCODE_AC_SIZE;
            end else begin
                // Use extended run-length encoding
                next_state = ENCODE_AC_SIZE;
            end
        end

        ENCODE_AC_SIZE: begin
            encoded_bits = huffman_code;
            bit_length = huffman_len;

            if (size_category > 0) begin
                // Encode amplitude for AC coefficient
                encoded_bits = (huffman_code << size_category) |
                              (value_amplitude & ((1 << size_category) - 1));
                bit_length = huffman_len + size_category;
            end

            next_state = ENCODE_AC_AMPLITUDE;
        end

        ENCODE_AC_AMPLITUDE: begin
            encoded_bits = huffman_code;
            bit_length = huffman_len;

            ac_counter = ac_counter + 1;
            next_state = GET_AC_COEFF;
        end

        CHECK_EOB: begin
            if (last_block) begin
                // Insert End-of-Block marker
                next_state = INSERT_EOB;
                eob_detected = 1'b1;
            end else begin
                next_state = COMPLETE;
            end
        end

        INSERT_EOB: begin
            // EOB code (0x00 with length 4 in simplified table)
            encoded_bits = ac_table[0].code;
            bit_length = ac_table[0].length;
            code_counter = code_counter + 1;
            next_state = FLUSH;
        end

        FLUSH: begin
            // Flush remaining bits
            if (bit_pos > 0) begin
                // Pad with zeros if necessary
                encoded_bits = bit_buffer;
                bit_length = bit_pos;
                bit_pos = 4'b0;
            end
            next_state = COMPLETE;
        end

        COMPLETE: begin
            done = 1'b1;
            next_state = IDLE;
        end

        WAIT: begin
            // Wait state for complex encoding
            next_state = ENCODE_DC;
        end
    endcase
end

